const body = pm.response.json();

const token = body.access_token ?? body.data?.access_token;

pm.test("AUTH-SA-01: Login devuelve HTTP 200", () => {
  pm.response.to.have.status(200);
});

pm.test("AUTH-SA-02: Recibe token JWT", () => {
  pm.expect(token).to.be.a("string").and.not.empty;
});

if (
  pm.response.code === 200 &&
  typeof token === "string" &&
  token.length > 0
) {
  pm.environment.set("token_superadmin", token);
} else {
  pm.environment.unset("token_superadmin");
}

